const $=id=>document.getElementById(id); const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function downloadText(filename,text,mime='text/html'){const blob=new Blob([text],{type:mime});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=filename;document.body.appendChild(a);a.click();setTimeout(()=>{URL.revokeObjectURL(a.href);a.remove()},1000)}
function setupCanvasZoom(){let z=1;const s=document.querySelector('.canvas-main'),r=$('zoomReadout');if(!s||!r)return;const apply=()=>{s.style.setProperty('--canvas-zoom',z);r.textContent=Math.round(z*100)+'%'};$('zoomOut')?.addEventListener('click',()=>{z=Math.max(.5,+(z-.1).toFixed(2));apply()});$('zoomIn')?.addEventListener('click',()=>{z=Math.min(1.6,+(z+.1).toFixed(2));apply()});$('zoomFit')?.addEventListener('click',()=>{z=1;apply()});apply()}
function setShell(title,icon,kicker,desc){document.title=title+' — TAMPtools';$('workspaceHero').innerHTML=`<div class="workspace-hero-card"><div class="workspace-title-block"><div class="workspace-icon">${icon}</div><div><p class="eyebrow">${kicker}</p><h1>${title}</h1><p>${desc}</p></div></div><div class="workspace-hero-actions"><a class="btn btn-soft" href="/templates.html">Templates</a><a class="btn btn-soft" href="/support.html">Support</a><a class="btn btn-primary" href="/dashboard.html">Dashboard</a></div></div>`}
function setupAutoDraft(key){const root=$('.canvas-main');if(!root)return;const els=[...root.querySelectorAll('input:not([type=file]):not([type=password]),textarea,select')].filter(e=>e.id);if(!els.length)return;const k='tamptools:auto:'+key;try{const saved=JSON.parse(localStorage.getItem(k)||'null');if(saved)els.forEach(e=>{if(saved[e.id]!==undefined)e.value=saved[e.id]})}catch{}let timer;const save=()=>{clearTimeout(timer);timer=setTimeout(()=>{const d={};els.forEach(e=>d[e.id]=e.value);try{localStorage.setItem(k,JSON.stringify(d))}catch{}},250)};els.forEach(e=>{e.addEventListener('input',save);e.addEventListener('change',save)})}function setupLocalDraft(key,ids){const k='tamptools:draft:'+key;const els=ids.map(id=>$(id)).filter(Boolean);if(!els.length)return;try{const saved=JSON.parse(localStorage.getItem(k)||'null');if(saved)els.forEach(e=>{if(saved[e.id]!==undefined)e.value=saved[e.id]})}catch{}let timer;const save=()=>{clearTimeout(timer);timer=setTimeout(()=>{const d={};els.forEach(e=>d[e.id]=e.value);try{localStorage.setItem(k,JSON.stringify(d))}catch{}},250)};els.forEach(e=>e.addEventListener('input',save));els.forEach(e=>e.addEventListener('change',save));}

