function setupImageModern(){
  let files=[],op='enhance',lastResult=null,zoom=1;
  const input=$('workspaceFiles'),queue=$('imageQueue'),form=$('imageForm'),stage=$('imageStage');
  const setStatus=(x)=>{$('imageStatus').textContent=x;$('studioStatus').textContent=x};
  const formatSize=n=>n<1024?`${n} B`:n<1048576?`${Math.round(n/1024)} KB`:`${(n/1048576).toFixed(1)} MB`;
  const renderQueue=()=>{if(!files.length){queue.innerHTML='<div class="image-queue-empty">Your selected images will appear here.</div>';return}queue.innerHTML=files.map((f,i)=>`<div class="image-queue-row"><img src="${URL.createObjectURL(f)}" alt=""><div><b>${esc(f.name)}</b><small>${formatSize(f.size)}</small></div><button type="button" class="image-remove-file" data-index="${i}" aria-label="Remove image">×</button></div>`).join('');queue.querySelectorAll('.image-remove-file').forEach(b=>b.onclick=()=>{files.splice(Number(b.dataset.index),1);renderQueue();renderStage();setStatus(files.length?`${files.length} image${files.length>1?'s':''} ready`:'Choose an image to begin.')})};
  const renderStage=()=>{if(!files.length){stage.innerHTML='<div class="image-stage-empty"><div class="stage-icon">✦</div><strong>Your image will appear here</strong><small>Upload an image to start editing.</small></div>';return}const src=URL.createObjectURL(files[0]);stage.innerHTML=`<img class="image-stage-image" id="activeImage" src="${src}" alt="${esc(files[0].name)}" style="transform:scale(${zoom})">`;stage.querySelector('img').onload=()=>{$('imageSelectionText').textContent=files.length>1?`${files.length} images selected • showing first`:files[0].name}};
  const forms={enhance:'<p>Improve light, contrast and detail for a cleaner image.</p>', 'remove-background':'<p>Remove the existing background and keep the main subject.</p>', 'background-color':'<label>Background color<input id="imgColor" type="color" value="#ffffff"></label>',resize:'<div class="image-form-grid"><label>Width<input id="imgW" type="number" min="100" max="6000" placeholder="1600"></label><label>Height<input id="imgH" type="number" min="100" max="6000" placeholder="1600"></label></div><label class="image-check"><input id="imgUpscale" type="checkbox"> Allow enlargement</label>',crop:'<div class="image-form-grid"><label>Width<input id="imgW" type="number" min="100" max="6000" placeholder="1200"></label><label>Height<input id="imgH" type="number" min="100" max="6000" placeholder="1200"></label></div>',compress:'<label>Quality <span id="qualityValue">80</span><input id="imgQuality" type="range" min="10" max="100" value="80"></label>',convert:'<label>Format<select id="imgFormat"><option value="webp">WEBP</option><option value="jpg">JPG</option><option value="png">PNG</option><option value="avif">AVIF</option></select></label>',watermark:'<label>Watermark text<input id="imgWatermark" maxlength="80" placeholder="Your brand"></label><label>Opacity <span id="opacityValue">45%</span><input id="imgOpacity" type="range" min="8" max="90" value="45"></label>',shadow:'<p>Add a soft product shadow to give the image more depth.</p>',reflection:'<p>Add a subtle reflection below the image.</p>'};
  const drawForm=()=>{form.innerHTML=forms[op]||'';const q=$('imgQuality');if(q)q.oninput=()=>{$('qualityValue').textContent=q.value};const o=$('imgOpacity');if(o)o.oninput=()=>{$('opacityValue').textContent=o.value+'%'}};
  document.querySelectorAll('[data-op]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-op]').forEach(x=>x.classList.remove('selected'));b.classList.add('selected');op=b.dataset.op;drawForm();setStatus(files.length?'Ready':'Choose an image to begin.')});
  input.onchange=()=>{files=[...input.files];renderQueue();renderStage();setStatus(files.length?`${files.length} image${files.length>1?'s':''} ready`:'Choose an image to begin.')};
  $('imageDrop').ondragover=e=>{e.preventDefault();$('imageDrop').classList.add('dragging')};$('imageDrop').ondragleave=()=>$('imageDrop').classList.remove('dragging');$('imageDrop').ondrop=e=>{e.preventDefault();$('imageDrop').classList.remove('dragging');files=[...e.dataTransfer.files].filter(f=>/^image\/(png|jpeg|webp|avif)$/.test(f.type)).slice(0,20);renderQueue();renderStage();setStatus(files.length?`${files.length} image${files.length>1?'s':''} ready`:'No supported images found.')};
  const settings=()=>{const s={format:'webp'};if(op==='background-color')s.backgroundColor=$('imgColor').value;if(op==='resize'||op==='crop'){s.width=Number($('imgW').value)||1200;s.height=Number($('imgH').value)||1200;s.fit=op==='crop'?'cover':'inside';s.upscale=$('imgUpscale')?.checked===true}if(op==='compress')s.quality=Number($('imgQuality').value)||80;if(op==='convert')s.format=$('imgFormat').value;if(op==='watermark'){s.text=$('imgWatermark').value||'TAMPtools';s.opacity=(Number($('imgOpacity').value)||45)/100}s.format=op==='remove-background'?'png':s.format;return s};
  const showResult=(data,original)=>{lastResult=data;const url=data.image?.url;if(!url)return;stage.innerHTML=`<img class="image-stage-image" id="activeImage" src="${url}" alt="Processed image">`;const compare=$('imageCompare');compare.hidden=false;$('imageBefore').style.backgroundImage=`url(${URL.createObjectURL(original)})`;$('imageAfter').style.backgroundImage=`url(${url})`;$('imageDownload').disabled=false;$('imageDownload').onclick=()=>{const a=document.createElement('a');a.href=url;a.download=data.filename||'tamptools-image';a.click()}};
  $('imageProcess').onclick=async()=>{if(!files.length)return setStatus('Choose an image first.');setStatus(files.length>1?'Processing images…':'Processing…');$('imageProcess').disabled=true;try{const fd=new FormData();const isBatch=files.length>1;const endpoint=isBatch?'/api/image-studio/batch':'/api/image-studio/process';(isBatch?files:files.slice(0,1)).forEach(f=>fd.append(isBatch?'files':'file',f));fd.append('operation',op);Object.entries(settings()).forEach(([k,v])=>fd.append(k,String(v)));const r=await fetch(endpoint,{method:'POST',credentials:'include',body:fd});const d=await r.json();if(!r.ok)throw Error(d.error||'Image processing failed.');if(isBatch){const first=d.results?.[0];if(first)showResult(first,files[0]);setStatus(`${d.results?.length||files.length} images processed`)}else{showResult(d,files[0]);setStatus('Done — your result is ready.')}}catch(e){setStatus(e.message||'Something went wrong.')}finally{$('imageProcess').disabled=false}};
  $('imageClear').onclick=()=>{files=[];lastResult=null;input.value='';$('imageCompare').hidden=true;$('imageDownload').disabled=true;renderQueue();renderStage();setStatus('Choose an image to begin.')};
  $('imageZoomOut').onclick=()=>{zoom=Math.max(.6,+(zoom-.1).toFixed(2));renderStage()};$('imageZoomIn').onclick=()=>{zoom=Math.min(1.6,+(zoom+.1).toFixed(2));renderStage()};
  document.querySelectorAll('.image-side-preset').forEach(b=>b.onclick=()=>{const map={product:'enhance',white:'background-color',marketplace:'resize',shadow:'shadow'};op=map[b.dataset.preset];document.querySelectorAll('[data-op]').forEach(x=>x.classList.toggle('selected',x.dataset.op===op));drawForm();if(op==='resize'){$('imgW').value=1200;$('imgH').value=1200}if(op==='background-color')$('imgColor').value='#ffffff';setStatus(files.length?'Preset selected':'Choose an image to use this preset.')});
  document.querySelectorAll('[data-start]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-start]').forEach(x=>x.classList.remove('active'));b.classList.add('active');if(b.dataset.start==='batch'){input.multiple=true;input.click()}else if(b.dataset.start==='template'){document.querySelector('[data-preset="product"]')?.click()}else input.click()});
  drawForm();renderQueue();renderStage();
}
