    coupon:field('Offer / coupon URL','qrUrl','url','https://example.com/offer',true)+field('Title','qrTitle','text','20% off'),feedback:field('Feedback URL','qrUrl','url','https://example.com/feedback',true),video:field('Video URL','qrUrl','url','https://youtube.com/...',true),images:field('Gallery URL','qrUrl','url','https://example.com/gallery',true),pdf:field('PDF URL','qrUrl','url','https://example.com/file.pdf',true),menu:field('Menu URL','qrUrl','url','https://example.com/menu',true),mp3:field('Audio URL','qrUrl','url','https://example.com/audio.mp3',true),
