  const loadCaps=async()=>{try{caps=await (await fetch('/api/tools/qr-code/capabilities',{credentials:'include',cache:'no-store'})).json()}catch{} updateLocks(); if(!caps.features.staticTypes.includes(selectedType))selectedType='url';renderFields()};
  document.querySelectorAll('.qr-mode').forEach(b=>b.onclick=()=>{if(b.disabled)return;document.querySelectorAll('.qr-mode').forEach(x=>x.classList.remove('active'));b.classList.add('active');mode=b.dataset.mode;updateLocks()});
