  <section class="resume-card"><div class="resume-card-head"><div><span class="card-kicker">3 · Experience</span><h3>Show results, not just responsibilities</h3></div><button class="btn btn-soft" id="rAddExp" type="button">＋ Add experience</button></div><div id="rExperience"></div></section>
