  const addEdu=()=>{const wrap=document.createElement('div');wrap.className='resume-repeat';wrap.innerHTML=`<div class="form-grid three"><label class="field"><span>Degree / qualification</span><input class="input ed-degree"></label><label class="field"><span>School</span><input class="input ed-school"></label><label class="field"><span>Dates</span><input class="input ed-dates"></label></div><button type="button" class="btn btn-soft resume-remove">Remove</button>`;wrap.querySelector('.resume-remove').onclick=()=>{wrap.remove();renderPreview()};$r('rEducation').appendChild(wrap);wrap.querySelectorAll('input').forEach(x=>x.oninput=renderPreview);};
  const addCert=()=>{const wrap=document.createElement('div');wrap.className='resume-repeat';wrap.innerHTML=`<div class="form-grid three"><label class="field"><span>Certification</span><input class="input ce-name"></label><label class="field"><span>Issuer</span><input class="input ce-issuer"></label><label class="field"><span>Date</span><input class="input ce-date"></label></div><button type="button" class="btn btn-soft resume-remove">Remove</button>`;wrap.querySelector('.resume-remove').onclick=()=>wrap.remove();$r('rCertifications').appendChild(wrap);};
  const data=()=>({name:$r('rName').value.trim(),title:$r('rTitle').value.trim(),email:$r('rEmail').value.trim(),phone:$r('rPhone').value.trim(),location:$r('rLocation').value.trim(),linkedin:$r('rLinkedin').value.trim(),website:$r('rWebsite').value.trim(),targetJob:$r('rTarget').value.trim(),summary:$r('rSummary').value.trim(),jobDescription:$r('rJobDescription').value.trim(),template,skills:$r('rSkills').value.split(/[\n,]/).map(x=>x.trim()).filter(Boolean),experience:[...document.querySelectorAll('.resume-repeat')].filter(x=>x.querySelector('.ex-role')).map(x=>({role:x.querySelector('.ex-role').value,company:x.querySelector('.ex-company').value,dates:x.querySelector('.ex-dates').value,location:x.querySelector('.ex-location').value,bullets:x.querySelector('.ex-bullets').value.split('\n').map(x=>x.trim()).filter(Boolean)})),education:[...document.querySelectorAll('.resume-repeat')].filter(x=>x.querySelector('.ed-degree')).map(x=>({degree:x.querySelector('.ed-degree').value,school:x.querySelector('.ed-school').value,dates:x.querySelector('.ed-dates').value})),certifications:[...document.querySelectorAll('.resume-repeat')].filter(x=>x.querySelector('.ce-name')).map(x=>({name:x.querySelector('.ce-name').value,issuer:x.querySelector('.ce-issuer').value,date:x.querySelector('.ce-date').value}))});
  const renderPreview=()=>{const d=data();$r('rPreviewName').textContent=d.name||'Your resume';$r('rPreviewTemplate').textContent=templateMeta[template]?.[0]||template;$r('rPaper').innerHTML=`<div class="resume-paper-name">${esc2(d.name||'Your Name')}</div><div class="resume-paper-title">${esc2(d.title||'Professional Title')}</div><div class="resume-paper-contact">${esc2([d.email,d.phone,d.location].filter(Boolean).join(' · ')||'Email · Phone · Location')}</div><hr>${d.summary?`<h4>Professional Summary</h4><p>${esc2(d.summary)}</p>`:''}${d.experience.length?`<h4>Experience</h4>${d.experience.map(e=>`<div class="paper-job"><b>${esc2(e.role||'Role')}</b> · ${esc2(e.company||'Company')} <small>${esc2(e.dates)}</small>${e.bullets.map(b=>`<div>• ${esc2(b)}</div>`).join('')}</div>`).join('')}`:'<h4>Experience</h4><p class="paper-muted">Add your experience to see it here.</p>'}${d.education.length?`<h4>Education</h4>${d.education.map(e=>`<p><b>${esc2(e.degree)}</b> · ${esc2(e.school)} ${esc2(e.dates)}</p>`).join('')}`:''}${d.skills.length?`<h4>Skills</h4><p>${esc2(d.skills.join(' · '))}</p>`:''}${d.certifications.length?`<h4>Certifications</h4>${d.certifications.map(e=>`<p>${esc2(e.name)} · ${esc2(e.issuer)} ${esc2(e.date)}</p>`).join('')}`:''}`;updateScore(d)};
  const updateScore=async d=>{if(!caps.features.ats){$r('rScore').textContent='Free';$r('rScoreText').textContent='Upgrade to Lite for ATS readiness checks.';return}let score=0;if(d.name)score+=8;if(d.email&&d.phone)score+=8;if(d.summary)score+=12;if(d.experience.length)score+=15;if(d.experience.reduce((n,e)=>n+e.bullets.length,0)>=3)score+=15;if(d.education.length)score+=10;if(d.skills.length>=5)score+=12;if(d.targetJob)score+=8;if(d.jobDescription)score+=12;$r('rScore').textContent=score;$r('rScoreText').textContent=score>=80?'Strong structure — ready to generate.':score>=60?'Good foundation — add missing sections for a stronger application.':'Add more role-specific detail, achievements and skills.';$r('rAtsNote').textContent=score>=80?'Good ATS foundation. Review keywords and measurable achievements before exporting.':'ATS check: strengthen missing sections, measurable achievements and role-specific keywords.'};
