  const $r=id=>document.getElementById(id), data=()=>({name:$r('clName').value.trim(),title:$r('clTitle').value.trim(),email:$r('clEmail').value.trim(),phone:$r('clPhone').value.trim(),location:$r('clLocation').value.trim(),linkedin:$r('clLinkedin').value.trim(),employer:$r('clEmployer').value.trim(),position:$r('clPosition').value.trim(),hiringManager:$r('clManager').value.trim(),employerAddress:$r('clEmployerAddress').value.trim(),date:$r('clDate').value.trim(),jobDescription:$r('clJob').value.trim(),tone:$r('clTone').value,keySkills:$r('clSkills').value.split(',').map(x=>x.trim()).filter(Boolean),highlights:$r('clHighlights').value.split('\n').map(x=>x.trim()).filter(Boolean),motivation:$r('clMotivation').value.trim(),closing:$r('clClosing').value.trim(),template});
