  const load=async()=>{try{caps=await (await fetch('/api/tools/cover-letter-builder/capabilities',{credentials:'include',cache:'no-store'})).json()}catch{}$r('clPlan').textContent=caps.plan;$r('clTierTitle').textContent=caps.plan;const n=caps.limits?.projects==='All'?'Unlimited':caps.limits?.projects||2;$r('clTierText').textContent=`${n} letters/month · ${(caps.features.templates||[]).length} templates · ${caps.features.ai?'AI tailoring enabled':'core generation'}.`;if(!(caps.features.templates||[]).includes(template))template=(caps.features.templates||['professional'])[0];renderTemplates();renderPreview()};
