  setupLocalDraft('cover-letter-builder',['clName','clTitle','clEmail','clPhone','clLocation','clLinkedin','clEmployer','clPosition','clManager','clEmployerAddress','clDate','clSkills','clJob','clMotivation','clHighlights','clClosing']);
  $r('clGenerate').onclick=async()=>{const d=data();if(!d.name||!d.employer||!d.position)return $r('clStatus').textContent='Enter your name, employer and position first.';$r('clGenerate').disabled=true;$r('clStatus').textContent='Generating your tailored letter…';try{const r=await fetch('/api/tools/cover-letter-builder/generate',{method:'POST',credentials:'include',headers:{'Content-Type':'application/json'},body:JSON.stringify(d)});const j=await r.json();if(!r.ok)throw Error(j.error||'Unable to generate cover letter.');letter=j.coverLetter.text;ats=j.coverLetter.ats;$r('clPaper').innerHTML=`<div class="paper-name">${esc(d.name)}</div><div class="paper-contact">${esc([d.title,d.email,d.phone,d.location].filter(Boolean).join(' · '))}</div><hr><div class="generated-letter">${esc(letter).split('\n').map(x=>x?`<p>${x}</p>`:'<br>').join('')}</div>`;$r('clPreviewState').textContent='Generated';$r('clStatus').textContent=`Generated successfully${j.coverLetter.provider==='local'?'':' with AI tailoring'}.`;if(caps.features.ats){$r('clScore').textContent=ats.score;$r('clScoreText').textContent=`${ats.matchedKeywords||0} job-description keywords matched.`}$r('clDownloads').hidden=false;$r('clDownloads').innerHTML=`<a class="btn btn-soft" href="${j.coverLetter.pdf.downloadUrl}">Download PDF</a><a class="btn btn-soft" href="${j.coverLetter.docx.downloadUrl}">Download DOCX</a>`}catch(e){$r('clStatus').textContent=e.message}finally{$r('clGenerate').disabled=false}};load();
